package com.sivion.api.finance.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="finance_invoices",uniqueConstraints=@UniqueConstraint(name="uk_finance_invoice_sales_order",columnNames={"tenant_id","sales_order_id"})) public class Invoice { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="tenant_id",nullable=false) Long tenantId; @Column(nullable=false) String invoiceNumber; @Column(nullable=false) Long customerId; @Column(name="sales_order_id") Long salesOrderId; @Column(nullable=false) BigDecimal amount=BigDecimal.ZERO; @Column(nullable=false) String status="ISSUED"; @Column(nullable=false) Instant invoiceDate=Instant.now(); public Long getId(){return id;} public Long getTenantId(){return tenantId;} public void setTenantId(Long v){tenantId=v;} public String getInvoiceNumber(){return invoiceNumber;} public void setInvoiceNumber(String v){invoiceNumber=v;} public Long getCustomerId(){return customerId;} public void setCustomerId(Long v){customerId=v;} public Long getSalesOrderId(){return salesOrderId;} public void setSalesOrderId(Long v){salesOrderId=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){amount=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public Instant getInvoiceDate(){return invoiceDate;} }
